mapper.select:
SELECT al.activity_log_id AS activityLogId, UPPER(al.act) AS action, al.resource_id AS resourceId, al.resource_name AS resourceName, al.field AS fieldName, al.before_value AS beforeValue, al.after_value AS afterValue, al.user_id AS actorUserId, e.name AS actorName, e.resigned_at AS actorResignedAt, b.block_id AS blockId, b.title AS blockTitle, b.type AS blockType, al.created_at AS createdAt FROM activity_log al JOIN block b ON b.block_id = al.block_id JOIN step s ON s.step_id = b.step_id AND s.deleted_at IS NULL JOIN project p ON p.project_id = s.project_id AND p.company_id = #{companyId} AND p.deleted_at IS NULL JOIN employee e ON e.user_id = al.user_id AND e.company_id = p.company_id WHERE al.company_id = #{companyId} AND b.step_id = #{stepId} AND al.block_id IS NOT NULL
AND al.block_id = #{blockId}
AND al.activity_log_id < #{cursor}
ORDER BY al.activity_log_id DESC LIMIT #{limit}
